        return .tvOS
        #elseif os(watchOS)
        return .watchOS
        #elseif os(macOS)
        return .macOS
        #elseif os(visionOS)
        return .iPadOS
        #else
        switch UIDevice.current.userInterfaceIdiom {
        case .pad: return .iPadOS
        case .mac: return .macOS
        default: return .iOS
