    public static func font(_ style: TextStyle, _ platform: Platform) -> Font {
        let s = typeSpec(style, platform)
        return Font.custom(s.family, size: s.size, relativeTo: s.relativeTo).weight(s.weight)
    }
}

public extension View {
    /// Text in a theme type style: font, tracking and line spacing for the platform.
    func risographText(_ style: RisographTheme.TextStyle, platform: RisographTheme.Platform) -> some View {
        let s = RisographTheme.typeSpec(style, platform)
        return self.font(RisographTheme.font(style, platform)).tracking(s.tracking).lineSpacing(max(0, s.lineHeight - s.size))
    }

    /// A bar, sidebar or sheet background in the theme's material, opaque under Reduce Transparency.
    func risographMaterial(_ palette: RisographTheme.Palette, blur: CGFloat) -> some View {
        modifier(RisographThemeMaterialModifier(palette: palette, blur: blur))
    }
}

struct RisographThemeMaterialModifier: ViewModifier {
    let palette: RisographTheme.Palette
    let blur: CGFloat
    @Environment(\.accessibilityReduceTransparency) private var reduceTransparency
    func body(content: Content) -> some View {
        content.background {
            #if os(watchOS)
            Rectangle().fill(palette.materialSolid)
            #else
            if reduceTransparency || blur == 0 {
                Rectangle().fill(palette.materialSolid)
            } else {
                ZStack { Rectangle().fill(.ultraThinMaterial); Rectangle().fill(palette.material) }
            }
            #endif
        }
    }
}
